"""Color weather icons rendered from Noto Color Emoji (SD 16x16 + HD 32x32).

Icons are pre-rendered from the Noto Color Emoji font (SIL OFL).
https://fonts.google.com/noto/specimen/Noto+Color+Emoji

SD icons (16x16) are used for 128x32 displays.
HD icons (32x32) are used for 256x64 displays.
"""

from typing import Dict

from PIL import Image

# === SD Icons (16x16) ===

_SUN_HEX = ""

_PARTIAL_CLOUD_HEX = ""

_CLOUD_HEX = ""

_LIGHT_RAIN_HEX = ""

_RAIN_HEX = ""

_SNOW_HEX = ""

_THUNDERSTORM_HEX = ""

_FOG_HEX = ""


# === HD Icons (32x32) ===

_SUN_HD_HEX = ""

_PARTIAL_CLOUD_HD_HEX = ""

_CLOUD_HD_HEX = ""

_LIGHT_RAIN_HD_HEX = ""

_RAIN_HD_HEX = ""

_SNOW_HD_HEX = ""

_THUNDERSTORM_HD_HEX = ""

_FOG_HD_HEX = ""


def _hex_to_image(hex_data: str, size: int = 16) -> Image.Image:
    """Convert hex-encoded RGB data to a PIL Image."""
    return Image.frombytes("RGB", (size, size), bytes.fromhex(hex_data))


# Build icon images from embedded data
_ICON_IMAGES_SD: Dict[str, Image.Image] = {
    "sun": _hex_to_image(_SUN_HEX, 16),
    "partial_cloud": _hex_to_image(_PARTIAL_CLOUD_HEX, 16),
    "cloud": _hex_to_image(_CLOUD_HEX, 16),
    "light_rain": _hex_to_image(_LIGHT_RAIN_HEX, 16),
    "rain": _hex_to_image(_RAIN_HEX, 16),
    "snow": _hex_to_image(_SNOW_HEX, 16),
    "thunderstorm": _hex_to_image(_THUNDERSTORM_HEX, 16),
    "fog": _hex_to_image(_FOG_HEX, 16),
}

_ICON_IMAGES_HD: Dict[str, Image.Image] = {
    "sun": _hex_to_image(_SUN_HD_HEX, 32),
    "partial_cloud": _hex_to_image(_PARTIAL_CLOUD_HD_HEX, 32),
    "cloud": _hex_to_image(_CLOUD_HD_HEX, 32),
    "light_rain": _hex_to_image(_LIGHT_RAIN_HD_HEX, 32),
    "rain": _hex_to_image(_RAIN_HD_HEX, 32),
    "snow": _hex_to_image(_SNOW_HD_HEX, 32),
    "thunderstorm": _hex_to_image(_THUNDERSTORM_HD_HEX, 32),
    "fog": _hex_to_image(_FOG_HD_HEX, 32),
}


# Map WMO weather codes to icon keys
WMO_CODE_TO_ICON: Dict[int, str] = {
    0: "sun",
    1: "partial_cloud",
    2: "partial_cloud",
    3: "cloud",
    45: "fog",
    48: "fog",
    51: "light_rain",
    53: "light_rain",
    55: "light_rain",
    56: "light_rain",
    57: "light_rain",
    61: "rain",
    63: "rain",
    65: "rain",
    66: "rain",
    67: "rain",
    71: "snow",
    73: "snow",
    75: "snow",
    77: "snow",
    80: "rain",
    81: "rain",
    82: "rain",
    85: "snow",
    86: "snow",
    95: "thunderstorm",
    96: "thunderstorm",
    99: "thunderstorm",
}


def get_weather_icon_image(code: int, hd: bool = False) -> Image.Image:
    """Get the color RGB icon for a WMO weather code.

    Args:
        code: WMO weather interpretation code.
        hd: If True, return 32x32 HD icon. Otherwise 16x16 SD.

    Returns:
        PIL Image (16x16 or 32x32 RGB).
    """
    icon_key = WMO_CODE_TO_ICON.get(code, "cloud")
    icons = _ICON_IMAGES_HD if hd else _ICON_IMAGES_SD
    return icons[icon_key].copy()
